mapper.select:
SELECT /* getReadingReportCnt */ COUNT(1)
  FROM TM_REPORT
 WHERE USER_NUMB = #{userNumb}
   AND REPT_NUMB = #{reptNumb}
   AND REPT_STAT = #{readStat}

SELECT /* getTimerDtl */ TMRX_NUMB, USER_NUMB, REPT_NUMB, TMRX_STAT, STRT_DATE, LAST_STRT,
       ENDX_DATE, READ_SECS, REGI_DATE, UPDT_DATE
  FROM TM_RDTMRX
 WHERE USER_NUMB = #{userNumb}
   AND TMRX_NUMB = #{tmrxNumb}

  SELECT /* getReadingBookList */ REPORT.REPT_NUMB, BOOK.BOOK_TITL, BOOK.BOOK_CVIM
    FROM TM_REPORT REPORT
    JOIN TM_BKINFO BOOK ON BOOK.BOOK_NUMB = REPORT.BOOK_NUMB
   WHERE REPORT.USER_NUMB = #{userNumb}
     AND REPORT.REPT_STAT = #{readStat}
ORDER BY REPORT.REPT_NUMB DESC

   SELECT /* getTodayCompletedTimerList */ TIMER.TMRX_NUMB, TIMER.REPT_NUMB, TIMER.TMRX_STAT, TIMER.STRT_DATE,
          TIMER.ENDX_DATE, TIMER.READ_SECS, BOOK.BOOK_TITL, BOOK.BOOK_CVIM
     FROM TM_RDTMRX TIMER
LEFT JOIN TM_REPORT REPORT ON REPORT.REPT_NUMB = TIMER.REPT_NUMB
LEFT JOIN TM_BKINFO BOOK ON BOOK.BOOK_NUMB = REPORT.BOOK_NUMB
    WHERE TIMER.USER_NUMB = #{userNumb}
      AND TIMER.TMRX_STAT = #{completedStat}
      AND TIMER.ENDX_DATE >= #{todayStart}
      AND TIMER.ENDX_DATE < #{tomorrowStart}
 ORDER BY TIMER.ENDX_DATE DESC, TIMER.TMRX_NUMB DESC

  SELECT /* getDailyList */ READ_DATE, READ_SECS
    FROM TB_RDATDX
   WHERE USER_NUMB = #{userNumb}
     AND READ_DATE BETWEEN #{weekStart} AND #{weekEnd}
ORDER BY READ_DATE

mapper.update:
UPDATE /* uptTimer */
       TM_RDTMRX
   SET TMRX_STAT = #{tmrxStat},
       LAST_STRT = #{lastStrt},
       ENDX_DATE = #{endxDate},
       READ_SECS = #{readSecs},
       UPDT_DATE = #{updtDate}
 WHERE TMRX_NUMB = #{tmrxNumb}
   AND USER_NUMB = #{userNumb}

mapper.delete:
DELETE /* delExpiredTimer */
  FROM TM_RDTMRX
 WHERE TMRX_STAT = #{completedStat}
   AND ENDX_DATE < #{expireDate}
